class Solution {
    public int minimumCost(String sentence, int k) {
        String[] w = sentence.split(" ");
        int n = w.length;
        long[] dp = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            int len = -1;
            int j = i;
            for (; j < n; j++) {
                len += w[j].length() + 1;
                if (len > k) break;
            }
            if (j == n) { dp[i] = 0; continue; }
            dp[i] = Long.MAX_VALUE;
            len = -1;
            for (j = i; j < n; j++) {
                len += w[j].length() + 1;
                if (len > k) break;
                dp[i] = Math.min(dp[i], (long) (k - len) * (k - len) + dp[j + 1]);
            }
        }
        return (int) dp[0];
    }
}
